CREATE OR REPLACE FUNCTION public.refresh_governance_city(_city text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.governance_effects;d public.public_decisions;delta record;iv public.city_indicators;new_value integer;m public.municipal_mandates;tr public.municipal_treasuries;s public.governance_settings;target integer;p integer;pi public.public_issues;co public.consultations;lid uuid;inst uuid;nid uuid;BEGIN
PERFORM public.initialize_governance_city(_city); SELECT * INTO s FROM public.governance_settings WHERE id=1;
SELECT * INTO tr FROM public.municipal_treasuries WHERE city_id=_city FOR UPDATE;target:=GREATEST(0,floor(extract(epoch FROM(public.game_now()-tr.anchor))/(30*86400))::integer);
IF target>tr.last_period THEN FOR p IN tr.last_period+1..LEAST(target,tr.last_period+120) LOOP
INSERT INTO public.governance_periods VALUES(_city,p,tr.anchor+p*interval '30 days') ON CONFLICT DO NOTHING;
IF FOUND THEN INSERT INTO public.municipal_ledger(city_id,entry_key,category,amount,label,occurred_at) VALUES(_city,'income:'||_city||':'||p,'Recettes',s.monthly_income,'Dotation municipale fictive',tr.anchor+p*interval '30 days'),(_city,'expense:'||_city||':'||p,'Fonctionnement',-LEAST(s.monthly_expense,tr.balance+s.monthly_income),'Services municipaux — fonctionnement',tr.anchor+p*interval '30 days');
UPDATE public.municipal_treasuries SET balance=GREATEST(0,balance+s.monthly_income-s.monthly_expense),income=income+s.monthly_income,expenses=expenses+LEAST(s.monthly_expense,balance+s.monthly_income),last_period=p WHERE city_id=_city RETURNING * INTO tr;
SELECT id INTO lid FROM public.locations WHERE city_id=_city AND kind='place' AND accessible AND district_id IS NOT NULL ORDER BY id LIMIT 1;SELECT id INTO inst FROM public.institutions WHERE city_id=_city AND type='Mairie' ORDER BY id LIMIT 1;
INSERT INTO public.public_issues(issue_key,institution_id,city_id,district_id,location_id,title,description,category,severity,appeared_at,governance_managed,indicator) SELECT 'governance:period:'||_city||':'||p,inst,_city,l.district_id,l.id,'Équipements du quartier à entretenir','Un contrôle municipal signale des équipements vieillissants. Le dossier peut être étudié pendant le mandat.','Équipements publics',2,tr.anchor+p*interval '30 days',true,'services' FROM public.locations l WHERE l.id=lid ON CONFLICT(issue_key) DO NOTHING;
END IF; END LOOP; END IF;
FOR e IN SELECT ef.* FROM public.governance_effects ef JOIN public.public_decisions dd ON dd.id=ef.decision_id WHERE dd.city_id=_city AND ef.applied_at IS NULL AND ef.due_at<=public.game_now() ORDER BY ef.due_at,CASE ef.kind WHEN 'immediate' THEN 0 WHEN 'completion' THEN 1 ELSE 2 END,ef.id LIMIT 500 FOR UPDATE OF ef LOOP
SELECT * INTO d FROM public.public_decisions WHERE id=e.decision_id FOR UPDATE;
UPDATE public.governance_effects SET applied_at=e.due_at WHERE id=e.id AND applied_at IS NULL; IF NOT FOUND THEN CONTINUE; END IF;
FOR delta IN SELECT key,value FROM jsonb_each_text(e.deltas) LOOP
SELECT * INTO iv FROM public.city_indicators WHERE city_id=_city AND indicator=delta.key FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Indicateur inconnu : %',delta.key; END IF;
new_value:=GREATEST(0,LEAST(100,iv.value+CASE WHEN d.compromise AND delta.value::integer>0 THEN floor(delta.value::integer*0.8)::integer ELSE delta.value::integer END));
INSERT INTO public.indicator_history(city_id,indicator,before_value,after_value,effect_key,occurred_at) VALUES(_city,delta.key,iv.value,new_value,e.effect_key,e.due_at) ON CONFLICT DO NOTHING;
UPDATE public.city_indicators SET value=new_value WHERE city_id=_city AND indicator=delta.key;
UPDATE public.public_decisions SET impact_real=jsonb_set(impact_real,ARRAY[delta.key],to_jsonb(COALESCE((impact_real->>delta.key)::integer,0)+new_value-iv.value)) WHERE id=d.id;
END LOOP;
IF e.kind='immediate' THEN PERFORM public.governance_news(d.id,'citizens','Réactions des habitants — '||d.title,CASE WHEN COALESCE((e.deltas->>'satisfaction')::integer,0)<0 THEN 'Des habitants expriment leur mécontentement face aux perturbations temporaires.' ELSE 'Les habitants manifestent leur intérêt pour le projet et attendent ses effets.' END,e.due_at,'citizens');
ELSIF e.kind='completion' THEN
UPDATE public.public_decisions SET workflow=CASE WHEN failure THEN 'abandoned' ELSE 'completed' END,completed_at=e.due_at WHERE id=d.id;
IF d.issue_id IS NOT NULL AND NOT d.failure THEN UPDATE public.public_issues SET status='resolved',stage=4 WHERE id=d.issue_id;INSERT INTO public.issue_history(issue_id,status,description,occurred_at) VALUES(d.issue_id,'resolved','Le projet municipal apporte une solution au problème.',e.due_at) ON CONFLICT DO NOTHING;END IF;
IF NOT EXISTS(SELECT 1 FROM public.public_decisions newer WHERE newer.location_id=d.location_id AND newer.id<>d.id AND newer.funded_at>d.funded_at AND newer.workflow='running') THEN UPDATE public.locations SET civic_state=CASE WHEN d.failure THEN 'projet' ELSE 'renove' END,civic_project=CASE WHEN d.failure THEN 'Projet interrompu : ' ELSE 'Projet terminé : ' END||d.title WHERE id=d.location_id; END IF;
nid:=public.governance_news(d.id,'completion',CASE WHEN d.failure THEN 'Projet interrompu — ' ELSE 'Projet terminé — ' END||d.title,CASE WHEN d.failure THEN 'La réalisation rencontre un échec technique. Le budget engagé reste dépensé ; la satisfaction diminue. Aucun remboursement personnel.' ELSE 'Les travaux sont achevés. Les premiers effets sont visibles ; certains bénéfices apparaîtront plus tard.' END,e.due_at,CASE WHEN d.failure THEN 'controversy' ELSE 'success' END);
INSERT INTO public.public_issues(issue_key,institution_id,city_id,district_id,location_id,title,description,category,severity,appeared_at,governance_managed,indicator) VALUES('governance:followup:'||d.id,d.institution_id,d.city_id,d.district_id,d.location_id,CASE WHEN d.failure THEN 'Réexamen du projet interrompu' ELSE 'Entretien du nouvel équipement' END,'Un nouveau dossier de suivi municipal est nécessaire.','Équipements publics',CASE WHEN d.failure THEN 4 ELSE 1 END,e.due_at,true,COALESCE(d.rule_snapshot->>'indicator','services')) ON CONFLICT(issue_key) DO NOTHING;
ELSIF e.kind='delayed' AND NOT d.failure THEN PERFORM public.governance_news(d.id,'delayed','Bilan des premiers effets — '||d.title,'Les effets différés du projet sont maintenant mesurés dans les indicateurs de la ville.',e.due_at,'report');END IF;
END LOOP;
FOR co IN SELECT * FROM public.consultations WHERE city_id=_city AND advisory AND status='open' AND ends_at<=public.game_now() ORDER BY ends_at,id FOR UPDATE LOOP
UPDATE public.consultations SET status='closed',closed_at=ends_at WHERE id=co.id;
PERFORM public.governance_news(co.governance_decision_id,'consultation-closed','Avis citoyens recueillis — '||co.title,(SELECT count(*) FROM public.consultation_participations WHERE consultation_id=co.id)||' participations. Ces avis éclairent la discussion sans imposer le résultat du conseil.',co.ends_at,'consultation');
END LOOP;
FOR pi IN SELECT * FROM public.public_issues WHERE city_id=_city AND governance_managed AND status<>'resolved' AND appeared_at+interval '7 days'<=public.game_now() ORDER BY id FOR UPDATE LOOP
p:=LEAST(4,GREATEST(0,floor(extract(epoch FROM(public.game_now()-pi.appeared_at))/(7*86400))::integer));
IF p>pi.stage THEN UPDATE public.public_issues SET stage=p,severity=LEAST(5,severity+1),governance_delta=governance_delta+1,status='identified' WHERE id=pi.id;INSERT INTO public.issue_history(issue_id,status,description,occurred_at) VALUES(pi.id,'identified','Le problème persiste : sa gravité augmente en attente d’une solution.',pi.appeared_at+p*interval '7 days') ON CONFLICT DO NOTHING;END IF;END LOOP;
FOR m IN SELECT * FROM public.municipal_mandates WHERE city_id=_city AND closing_indicators IS NULL AND (ends_at<=public.game_now() OR EXISTS(SELECT 1 FROM public.municipal_mandates newer WHERE newer.city_id=_city AND newer.starts_at>municipal_mandates.starts_at AND newer.starts_at<=public.game_now())) ORDER BY starts_at,id FOR UPDATE LOOP
UPDATE public.municipal_mandates SET status='ended',closing_indicators=(SELECT jsonb_object_agg(indicator,value) FROM public.city_indicators WHERE city_id=_city),final_report=jsonb_build_object('completed',(SELECT count(*) FROM public.public_decisions WHERE mandate_id=m.id AND workflow='completed'),'abandoned',(SELECT count(*) FROM public.public_decisions WHERE mandate_id=m.id AND workflow='abandoned'),'rejected',(SELECT count(*) FROM public.public_decisions WHERE mandate_id=m.id AND workflow='rejected'),'spent',COALESCE((SELECT sum(cost) FROM public.public_decisions WHERE mandate_id=m.id AND funded_at IS NOT NULL),0)) WHERE id=m.id;
END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.refresh_governance_city(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_governance_city(text) TO service_role;
CREATE OR REPLACE FUNCTION public.refresh_governance_world() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ci text;n integer:=0;BEGIN FOR ci IN SELECT id FROM public.cities ORDER BY id LOOP PERFORM public.refresh_governance_city(ci);n:=n+1;END LOOP;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.refresh_governance_world() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.refresh_governance_world() TO service_role;
CREATE OR REPLACE FUNCTION public.settle_governance_politics(_cid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.public_decisions;ps public.political_stats;rep integer;inf integer;s public.political_settings;BEGIN
IF NOT EXISTS(SELECT 1 FROM public.characters WHERE id=_cid AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Non autorisé';END IF;
INSERT INTO public.political_stats(character_id) VALUES(_cid) ON CONFLICT DO NOTHING;SELECT * INTO ps FROM public.political_stats WHERE character_id=_cid FOR UPDATE;SELECT * INTO s FROM public.political_settings WHERE id=1;
FOR d IN SELECT dd.* FROM public.public_decisions dd JOIN public.municipal_mandates mm ON mm.id=dd.mandate_id JOIN public.candidacies ca ON ca.id=mm.candidacy_id WHERE ca.character_id=_cid AND dd.completed_at IS NOT NULL AND dd.political_settled_at IS NULL ORDER BY dd.completed_at,dd.id FOR UPDATE OF dd LOOP
rep:=CASE WHEN d.failure THEN -3 ELSE COALESCE((d.rule_snapshot->>'reputation_gain')::integer,3) END;inf:=CASE WHEN d.failure THEN -1 ELSE COALESCE((d.rule_snapshot->>'influence_gain')::integer,1) END;
INSERT INTO public.political_rewards(character_id,reward_key,kind,reputation,influence,label,occurred_at) VALUES(_cid,'governance:'||d.id,'governance',rep,inf,CASE WHEN d.failure THEN 'Échec municipal — ' ELSE 'Projet municipal — ' END||d.title,d.completed_at) ON CONFLICT DO NOTHING;
IF FOUND THEN UPDATE public.political_stats SET reputation=GREATEST(0,LEAST(s.stat_cap,reputation+rep)),influence=GREATEST(0,LEAST(s.stat_cap,influence+inf)) WHERE character_id=_cid;END IF;
UPDATE public.public_decisions SET political_settled_at=public.game_now() WHERE id=d.id;
END LOOP;
UPDATE public.municipal_mandates mm SET closing_politics=(SELECT jsonb_build_object('reputation',reputation,'influence',influence) FROM public.political_stats WHERE character_id=_cid) FROM public.candidacies ca WHERE ca.id=mm.candidacy_id AND ca.character_id=_cid AND mm.status='ended' AND mm.closing_politics IS NULL;
END $$;
REVOKE ALL ON FUNCTION public.settle_governance_politics(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.settle_governance_politics(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.governance_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid;c public.characters;m public.municipal_mandates;BEGIN
cid:=public.prepare_daily_life();SELECT * INTO c FROM public.characters WHERE id=cid;PERFORM public.refresh_governance_city(c.city_id);PERFORM public.settle_governance_politics(cid);
SELECT * INTO m FROM public.municipal_mandates WHERE city_id=c.city_id AND starts_at<=public.game_now() ORDER BY starts_at DESC,id LIMIT 1;
RETURN jsonb_build_object('world_now',public.game_now(),'character_id',cid,'city_id',c.city_id,'city_name',(SELECT name FROM public.cities WHERE id=c.city_id),'energy',(SELECT energy FROM public.characters WHERE id=cid),'position_id',(SELECT location_id FROM public.character_positions WHERE character_id=cid),'stats',(SELECT jsonb_build_object('reputation',reputation,'influence',influence) FROM public.political_stats WHERE character_id=cid),'settings',(SELECT to_jsonb(gs) FROM public.governance_settings gs WHERE id=1),
'mandate',CASE WHEN m.id IS NULL THEN NULL ELSE jsonb_build_object('id',m.id,'function',m.function,'starts_at',m.starts_at,'ends_at',m.ends_at,'status',m.status,'mine',EXISTS(SELECT 1 FROM public.candidacies WHERE id=m.candidacy_id AND character_id=cid),'holder',(SELECT display_name FROM public.candidacies WHERE id=m.candidacy_id),'party',(SELECT o.name FROM public.organizations o JOIN public.candidacies ca ON ca.organization_id=o.id WHERE ca.id=m.candidacy_id),'priorities',m.priorities,'opening_indicators',m.opening_indicators,'closing_indicators',m.closing_indicators,'opening_politics',CASE WHEN EXISTS(SELECT 1 FROM public.candidacies WHERE id=m.candidacy_id AND character_id=cid) THEN m.opening_politics END,'closing_politics',CASE WHEN EXISTS(SELECT 1 FROM public.candidacies WHERE id=m.candidacy_id AND character_id=cid) THEN m.closing_politics END,'final_report',m.final_report) END,
'indicators',COALESCE((SELECT jsonb_agg(jsonb_build_object('indicator',ci.indicator,'value',ci.value,'baseline',ci.baseline,'weekly_delta',COALESCE((SELECT sum(after_value-before_value) FROM public.indicator_history h WHERE h.city_id=c.city_id AND h.indicator=ci.indicator AND h.occurred_at>public.game_now()-interval '7 days'),0)) ORDER BY ci.indicator) FROM public.city_indicators ci WHERE ci.city_id=c.city_id),'[]'),
 'treasury',(SELECT to_jsonb(t) FROM public.municipal_treasuries t WHERE city_id=c.city_id),
 'groups',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'seats',g.seats,'majority',g.majority,'base_support',g.base_support,'organization_id',g.organization_id,'ideology',g.ideology,'leader',(SELECT jsonb_build_object('id',n.id,'name',n.first_name||' '||n.last_name,'location',to_jsonb(l),'relation',(SELECT score FROM public.social_relations WHERE character_id=cid AND npc_id=n.id)) FROM public.social_npcs n JOIN public.locations l ON l.id=n.location_id WHERE n.id=g.leader_id)) ORDER BY g.seats DESC,g.id) FROM public.municipal_council_groups g WHERE mandate_id=m.id),'[]'),
 'rules',COALESCE((SELECT jsonb_agg(r ORDER BY r.id) FROM public.governance_rules r),'[]'),
 'projects',COALESCE((SELECT jsonb_agg(to_jsonb(d)||jsonb_build_object('location',to_jsonb(l),'district_name',di.name,'responsible',ins.name,'positions',COALESCE((SELECT jsonb_agg(pos) FROM public.governance_positions pos WHERE decision_id=d.id),'[]'),'actions',COALESCE((SELECT jsonb_agg(jsonb_build_object('command',ga.command,'activity_id',ga.activity_id,'group_id',ga.group_id,'settled_at',ga.settled_at)) FROM public.governance_actions ga WHERE ga.decision_id=d.id AND ga.character_id=cid),'[]')) ORDER BY d.decided_at DESC,d.id) FROM public.public_decisions d JOIN public.locations l ON l.id=d.location_id LEFT JOIN public.districts di ON di.id=d.district_id JOIN public.institutions ins ON ins.id=d.institution_id WHERE d.city_id=c.city_id AND d.mandate_id=m.id),'[]'),
 'issues',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',i.id,'title',i.title,'severity',i.severity,'indicator',COALESCE(i.indicator,'services'),'status',i.status,'district_name',di.name,'location',to_jsonb(l),'governance_delta',i.governance_delta) ORDER BY severity DESC,i.id) FROM public.public_issues i JOIN public.locations l ON l.id=i.location_id JOIN public.districts di ON di.id=i.district_id WHERE i.city_id=c.city_id),'[]'),
 'ledger',COALESCE((SELECT jsonb_agg(x ORDER BY occurred_at DESC) FROM (SELECT * FROM public.municipal_ledger WHERE city_id=c.city_id ORDER BY occurred_at DESC LIMIT 100) x),'[]'),
 'reactions',COALESCE((SELECT jsonb_agg(x ORDER BY occurred_at DESC) FROM (SELECT id,title,description,kind,occurred_at,news_id FROM public.governance_reactions WHERE city_id=c.city_id ORDER BY occurred_at DESC LIMIT 100) x),'[]'),
 'activities',COALESCE((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('location',to_jsonb(l)) ORDER BY a.start_time) FROM public.activities a JOIN public.locations l ON l.id=a.location_id WHERE a.character_id=cid AND a.type='governance' AND a.start_time>public.game_now()-interval '7 days'),'[]'));
END $$;
REVOKE ALL ON FUNCTION public.governance_state() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.governance_state() TO authenticated;